import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../App.css";

const Users = () => {
  const [users, setUsers] = useState([
    { id: 1, name: "JohnDoe", email: "john@example.com" },
    { id: 2, name: "FitQueen", email: "fitqueen@example.com" },
  ]);

  const banUser = (id) => {
    const confirmBan = window.confirm("Are you sure you want to ban this user?");
    if (confirmBan) {
      setUsers(users.filter((user) => user.id !== id));
    }
  };

  return (
    <div>
      <Navbar />
      <main className="favorites-wrapper">
        <h2>All Registered Users</h2>
        <div className="favorites-grid">
          {users.map((user) => (
            <div className="favorite-card" key={user.id}>
              <h4>{user.name}</h4>
              <p>Email: {user.email}</p>
              <button className="remove-btn" onClick={() => banUser(user.id)}>
                Ban/Delete User
              </button>
            </div>
          ))}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Users;
